#include "stdlib/blas/ext/base/ndarray/dcartesian_power.h"
#include "stdlib/blas/ext/base/dcartesian_power.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/blas/base/shared.h"
#include <stdint.h>

/**
* Computes the Cartesian power for a double-precision floating-point ndarray.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a two-dimensional output ndarray.
*     -   a zero-dimensional ndarray specifying the power.
*
* @param arrays    list containing ndarrays
*/
void stdlib_blas_ext_dcartesian_power( const struct ndarray *arrays[] ) {
	const struct ndarray *x = arrays[ 0 ];
	const struct ndarray *out = arrays[ 1 ];

	int32_t k;
	stdlib_ndarray_get_int32( arrays[ 2 ], NULL, &k );

	const CBLAS_INT N = stdlib_ndarray_dimension( x, 0 );

	const CBLAS_INT strideX = stdlib_ndarray_stride_elements( x, 0 );
	const CBLAS_INT offsetX = stdlib_ndarray_offset_elements( x );
	const CBLAS_INT strideOut1 = stdlib_ndarray_stride_elements( out, 0 );
	const CBLAS_INT strideOut2 = stdlib_ndarray_stride_elements( out, 1 );
	const CBLAS_INT offsetOut = stdlib_ndarray_offset_elements( out );

	const double *dataX = (const double *)stdlib_ndarray_data( x );
	double *dataOut = (double *)stdlib_ndarray_data( out );
	API_SUFFIX(stdlib_strided_dcartesian_power_ndarray)( N, (CBLAS_INT)k, dataX, strideX, offsetX, dataOut, strideOut1, strideOut2, offsetOut );
}
